import { privateKeyToAccount } from 'viem/accounts';
export class WalletStateSigner {
    constructor(walletClient) {
        this.walletClient = walletClient;
        this.address = walletClient?.account?.address ?? '0x';
    }
    async sign(data) {
        if (!this.walletClient?.signMessage) {
            throw new Error('WalletClient does not support signMessage');
        }
        return this.walletClient.signMessage({
            account: this.walletClient.account,
            message: { raw: data },
        });
    }
}
export function createECDSAMessageSigner(privateKey) {
    const account = privateKeyToAccount(privateKey);
    const encoder = new TextEncoder();
    const toSignableBytes = (payload) => {
        if (payload instanceof Uint8Array)
            return payload;
        const normalized = JSON.stringify(payload, (_key, value) => typeof value === 'bigint' ? value.toString() : value);
        return encoder.encode(normalized);
    };
    return async (payload) => {
        return account.signMessage({ message: { raw: toSignableBytes(payload) } });
    };
}
